    // Function to fetch locations
    var getLocations = async () => {
        try {
            const response = await fetch("/graphql", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Authorization": "Bearer {{settings.storefront_api.token}}"
                },
                body: JSON.stringify({
                    query: fetchLocations
                }),
            });
            const data = await response.json();

            const locations = data.data.inventory.locations.edges;

            return locations; // This returns a resolved list of locations

        } catch (error) {
            console.error("Error fetching store inventory information:", error);
        }
    };


    var fetchStockByLocation = 
    `query getStockByLocations($prodId: Int!, $variantId: Int!) {
        site {
            products (entityIds: [$prodId]) {
                edges {
                    node {
                        variants (entityIds:[$variantId]) {
                            edges {
                                node {
                                    entityId
                                    sku
                                    inventory {
                                        byLocation {
                                            edges {
                                                node {
                                                    locationEntityId
                                                    locationEntityCode
                                                    locationEntityTypeId
                                                    locationDistance {
                                                        value
                                                        lengthUnit
                                                    }
                                                    availableToSell
                                                    warningLevel
                                                    isInStock
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }`;

    const fetchProductVariants = async () => {
        var query = `
          query getProductVariants($prodId: Int!) {
            site {
                product (entityId: $prodId) {
                    variants (first:100) {
                        edges {
                            node {
                                entityId
                                isPurchasable
                            }
                        }
                    }
                }
            }
          }
        `;

        try {
            const response = await fetch("/graphql", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Authorization": "Bearer {{settings.storefront_api.token}}"
                },
                body: JSON.stringify({ 
                    query: query, 
                    variables: { prodId: parseInt(productId) } 
                }),
            });

            const data = await response.json();

            const purchasableVariant = data.data.site.product.variants.edges.find(
                edge => edge.node.isPurchasable
            );

            if(data.data.site.product.variants.edges.length == 1){
                $("#variantId").val(data.data.site.product.variants.edges[0].node.entityId);
            }

            if (purchasableVariant) {
                varId = purchasableVariant.node.entityId;
            } else {
                console.warn("No purchasable variant found.");
            }
        } catch (error) {
          console.error("Error fetching product variants:", error);
        }
    };

    var getStockByLocation = async (locations) => {
        try {
            /*
            const response = await fetch("/graphql", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Authorization": "Bearer {{settings.storefront_api.token}}"
                },
                body: JSON.stringify({
                    query: fetchStockByLocation,
                    variables: { prodId: parseInt(productId), variantId: varId }, 
                }),
            });
            const data = await response.json();
            */
            const options = {
                method: 'POST',
                headers: {Accept: 'application/json', 'Content-Type': 'application/json'},
                body: `{"searchArea":{"radius":{"value":9999,"unit":"KM"},"coordinates":{"latitude":40.4169473,"longitude":-3.7035285}},"items":[{"variantId":${varId},"quantity":1}]}`
            };

            const response = await fetch("/api/storefront/pickup-options", options);
            const data = await response.json();

            ///////////////////////////
            //console.log('locations',locations);
            //console.log('variantId', varId);

            const locationContainer = document.getElementById('location-container');
            locationContainer.innerHTML = '';

            const pickupOptions = data.results.flatMap(r => r.pickupOptions);

            const allOutOfStock = pickupOptions.length === 0;

            const stockMap = new Map();
            pickupOptions.forEach(opt => {
                const locId = opt.pickupMethod.locationId;
                const totalQty = opt.availableItems.reduce((sum, item) => sum + item.quantity, 0);
                stockMap.set(locId, totalQty);
            });

            const customLocationOrder = [
                'BC-TIENDA-2',
                'BC-TIENDA-3',
                'BC-TIENDA-4',
                'BC-TIENDA-7',
                'BC-TIENDA-5',
                'BC-TIENDA-8',
                'BC-TIENDA-1 - V1',
                'BC-TIENDA-6',
            ];

            locations.sort((a, b) => {
                const codeA = a.node.code;
                const codeB = b.node.code;

                const indexA = customLocationOrder.indexOf(codeA);
                const indexB = customLocationOrder.indexOf(codeB);

                if (indexA !== -1 && indexB !== -1) {
                    return indexA - indexB;
                }
                if (indexA !== -1) {
                    return -1;
                }
                if (indexB !== -1) {
                    return 1;
                }
                return codeA.localeCompare(codeB);
            });

            locations.forEach(location => {
                const { id: entityId, code, label, address, description } = location.node;
                const { address1, city, postalCode, latitude, longitude, phone } = address;

                if (code === 'CENTRAL' || code === 'ONLINE') return;

                const isInStock = stockMap.has(location.node.entityId);
                const availableToSell = stockMap.get(location.node.entityId) || 0;

                let availabilityMessage = '';
                let availabilityClass = '';

                if (allOutOfStock) {
                    // Caso 1: Todas las tiendas están agotadas
                    availabilityMessage = '<p class="no-stock-info" style="color: red;">{{lang 'products.stock_unavailable'}}</p>';
                    availabilityClass = 'red';

                } else if (availableToSell === 0 && !allOutOfStock) {
                    // Caso 2: Esta tienda no tiene unidades online, pero hay stock en otras
                    availabilityMessage = '<p class="limited-stock-info" style="color: orange;">{{lang 'products.stock_migration'}}</p>';
                    availabilityClass = 'orange';

                } else if (availableToSell > 0 && !isInStock) {
                    // Caso 3: Tiene stock físico en tienda, pero no online
                    availabilityMessage = '<p class="limited-stock-info" style="color: orange;">{{lang 'products.stock_in_store'}}</p>';
                    availabilityClass = 'orange';

                } else if (availableToSell > 0 && isInStock) {
                    // Caso 4: Stock online disponible
                    availabilityMessage = `<p class="stock-info" style="color: green;">{{lang 'products.in_stock'}}</p>`;
                    availabilityClass = 'green';
                }

                const div = document.createElement('div');
                div.classList.add('location-item');
                div.innerHTML = `
                    <b class="location-name">${label}</b>
                    <p class="location-addr">
                        ${address1}, ${postalCode}, ${city}<br>
                        ${description || ''}
                    </p>
                    ${phone ? `<p class="location-addr phone">Tel. ${phone}</p>` : ''}
                    <div class="location-availability">
                    <div class="availability-dot ${availabilityClass}"></div>
                        ${availabilityMessage}
                    </div>
                    <div class="open-map-link">
                        <a href="https://www.google.com/maps/place/${latitude},${longitude}/@${latitude},${longitude},21z" target="_blank">
                            {{lang 'products.maps'}}
                        </a>
                    </div>
                `;

                div.addEventListener('click', () => {
                    document.querySelectorAll('.location-item.selected-location')
                    .forEach(el => el.classList.remove('selected-location'));
                    div.classList.add('selected-location');
                    updateMapLocation(latitude, longitude);
                });

                locationContainer.appendChild(div);
            });


    } catch (error) {
        console.error("Error fetching store inventory information:", error);
    }
};

    var getOnlineStock = async () => {
        try {            
            if(varId !=null){
                const response = await fetch("/graphql", {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        "Authorization": "Bearer {{settings.storefront_api.token}}"
                    },
                    body: JSON.stringify({
                        query: fetchStockByLocation,
                        variables: { prodId: parseInt(productId), variantId: varId }, 
                    }),
                });
                const data = await response.json();            
                ///////////////////////////
                //console.log('variantId', varId);

                const byLocationEdges = data.data.site.products.edges[0].node.variants.edges[0].node.inventory.byLocation.edges;
                const onlineLocation = byLocationEdges.find(edge => edge.node.locationEntityCode === "ONLINE");
                const availableToSell = onlineLocation ? onlineLocation.node.availableToSell : null;

                const stockElement = document.querySelector('#availability-custom');
                if (stockElement) {
                    if (availableToSell !== null && availableToSell > 5) {
                        stockElement.innerHTML = `<div class="availability-dot green"></div><span>{{lang 'products.stock_available'}}</span>`;
                    }else if(availableToSell == null ||availableToSell == 0 ){
                        stockElement.innerHTML = `<div class="availability-dot red"></div><span>{{lang 'products.stock_unavailable'}}</span>`;
                    } 
                    else {
                        stockElement.innerHTML = 
                            `<div class="availability-dot"></div>
                            <span>{{lang 'products.last'}}</span>
                            <span class="stock_value">${availableToSell}</span>
                            <span>{{lang 'products.units'}}</span>`
                    }
                }    
            }            
        } catch (error) {
            console.error("Error fetching online inventory - ", error);
        }
    };


    var map;
    var marker;

    async function initMap() {
        const { Map } = await google.maps.importLibrary("maps");
        const { AdvancedMarkerElement } = await google.maps.importLibrary("marker");

        // Default center of the map (e.g., Barcelona)
        var defaultLocation = { lat: 41.3896, lng: 2.1634 };

        map = new Map(document.getElementById('map'), {
            zoom: 12,
            center: defaultLocation,
            mapId: 'storesMap',
        });

        // Create a marker at the default location
        marker = new AdvancedMarkerElement({
            position: defaultLocation,
            map: map,
        });
    }

    // Function to change the location on the map
    function updateMapLocation(lat, lng) {
        var location = { lat: lat, lng: lng };
        map.setCenter(location);
        marker.position = location;
    }

    const initializeProduct = async () => {
        if(hasOptions){  //CASE: CONFIG PRODUCT
            await fetchProductVariants();
            ProductOptionsEventScript();
            main();
        }else{
            await fetchProductVariants(); //CASE: SIMPLE PRODUCT
            main();
        }
    };

    initializeProduct();

    function ProductOptionsEventScript() {
        function productOptionsChangeHandler() {
            waitForJquery(addProductOptionsChangedListener)
        }

        async function addProductOptionsChangedListener() {
            // Get product option form
            const $productOptionsElement = $("[data-product-option-change]")

            $productOptionsElement.off('change').on('change', function (event) {
                const $changedOption = $(event.target);
                const $form = $changedOption.parents('form');
                //const productId = parseInt(productId);

                window.stencilUtils.api.productAttributes.optionChange(parseInt(productId), $form.serialize(), 'products/bulk-discount-rates', async (err, response) => {
                    const productAttributesData = response.data || {};
                    varId = productAttributesData.v3_variant_id;                    
                    $("#variantId").val(varId);
                    if(varId !=null){
                        await getOnlineStock();
                        locations = await getLocations();
                        await getStockByLocation(locations);     
                    }                
                });
            });
        }

        function waitForJquery(method) {
            if (window.jQuery) {
                method();
            } else {
                setTimeout(function() { waitForJquery(method) }, 50);
            }
        }

        productOptionsChangeHandler();
    }

    document.addEventListener("DOMContentLoaded", () => {
        if (typeof hasOptions !== 'undefined' && hasOptions) {
            initializeProduct();
        }
    });

    document.addEventListener("DOMContentLoaded", () => {
        const saleFlagElement = document.getElementById("dynamic-sale-flag");
        const saleFlagContainer = document.querySelector(".sale-flag-side");

        const parsePrice = (priceString) => {
            if (!priceString) return 0;
            // Remove any currency symbols and normalize the format
            const normalized = priceString.replace(/[^\d,.-]/g, '').replace('.', '').replace(',', '.');
            return parseFloat(normalized);
        };

        // Function to calculate and inject discount percentage
        const updateDiscountPercentage = () => {
            // Get the price elements
            const nonSalePriceElement = document.querySelector(".price--non-sale");
            const salePriceElement = document.querySelector(".price.red");

            if(saleFlagContainer){
                if (nonSalePriceElement && salePriceElement) {
                    // Parse the prices
                    const nonSalePrice = parsePrice(nonSalePriceElement.textContent);
                    const salePrice = parsePrice(salePriceElement.textContent);

                    // Calculate the discount percentage
                    if (nonSalePrice && salePrice && nonSalePrice > salePrice) {
                        const discountPercentage = ((nonSalePrice - salePrice) / nonSalePrice) * 100;
                        saleFlagElement.textContent = `- ${discountPercentage | 0}%`;
                        saleFlagContainer.style.display = "block"; // Show the container
                    } else {
                        saleFlagElement.textContent = ""; // No discount
                        saleFlagContainer.style.display = "none"; 
                    }
                } else {
                    saleFlagContainer.style.display = "none";
                }
            }
        };

        const priceContainer = document.querySelector(".productView-price");
        if (priceContainer) {
            const observer = new MutationObserver(() => {
                updateDiscountPercentage(); // Trigger when the DOM changes
            });

            observer.observe(priceContainer, { childList: true, subtree: true });
        }

        updateDiscountPercentage();
    });

</script>


