<script>
    document.addEventListener('DOMContentLoaded', () => {
        const thumbnails = document.querySelectorAll('.productView-thumbnail-link');
        const prevButton = document.querySelector('.image-carousel-prev');
        const nextButton = document.querySelector('.image-carousel-next');
        let activeIndex = 0;

        const updateButtonStates = () => {
            prevButton.disabled = activeIndex === 0;
            nextButton.disabled = activeIndex === thumbnails.length - 1;
        };

        updateButtonStates();

        // Previous button click
        prevButton.addEventListener('click', () => {
            if (activeIndex > 0) {
                activeIndex -= 1;
                thumbnails[activeIndex].click();
            }
            updateButtonStates();
        });

        // Next button click
        nextButton.addEventListener('click', () => {
            if (activeIndex < thumbnails.length - 1) {
                activeIndex += 1;
                thumbnails[activeIndex].click();
            }
            updateButtonStates();
        });

        // Update activeIndex on thumbnail click (in case navigation occurs outside buttons)
        thumbnails.forEach((thumbnail, index) => {
            thumbnail.addEventListener('click', () => {
                activeIndex = index;
                updateButtonStates();
            });
        });
    });    
</script>

<script>
    function formatNumber(numberString) {
        return parseFloat(numberString.replace(/\./g, '').replace(',', '.'));
    }

    function detectCurrencySymbol(priceElement) {
        const priceText = priceElement?.textContent.trim();
        return priceText ? priceText.replace(/[\d\s.,]/g, '') : '€';
    }

    function formatCurrency(value, currencySymbol) {
        return new Intl.NumberFormat('es-ES', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
            useGrouping: true
        }).format(value) + ` ${currencySymbol}`;
    }

    function updateSavings() {
        const salePriceEl = document.querySelector(".productView-main .productView-price [data-product-price-with-tax]");
        const nonSalePriceEl = document.querySelector(".productView-main .old-price [data-product-non-sale-price-with-tax]");
        const savingEl = document.querySelector(".productView-main .old-price .saving");

        if (salePriceEl && nonSalePriceEl && savingEl) {
            const salePrice = formatNumber(salePriceEl.textContent);
            const nonSalePrice = formatNumber(nonSalePriceEl.textContent);
            const currencySymbol = detectCurrencySymbol(salePriceEl);
            if (!isNaN(salePrice) && !isNaN(nonSalePrice)) {
                const saving = nonSalePrice - salePrice;
                savingEl.textContent = `Ahorras ${formatCurrency(saving, currencySymbol)}`;
            }
        }
    }

    updateSavings();

    const observerSavings = new MutationObserver(updateSavings);
    const priceElement = document.querySelector(".productView-main .productView-price [data-product-price-with-tax]");
    if (priceElement) {
        observerSavings.observe(priceElement, { childList: true, subtree: true });
    }
</script>

